"""Small published sanity expectations and shape checks, not a full image evaluator."""
import json,re
HEX=re.compile(r'[0-9a-f]+\Z')
def strict_loads(raw):
 def pairs(items):
  out={}
  for k,v in items:
   if k in out:raise ValueError('duplicate output key')
   out[k]=v
  return out
 return json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_constant=lambda x:(_ for _ in()).throw(ValueError(x)))
def fields(v,names):
 if type(v)is not dict or set(v)!=set(names.split()):raise ValueError('response fields')
def integer(x,lo,hi):return type(x)is int and lo<=x<=hi
def image_shape(d):
 fields(d,'root front16 front64 cells banks bitmaps nexthops')
 def loc(v):return type(v)is list and len(v)==2 and integer(v[0],0,10)and integer(v[1],0,131071)
 if d['root']is not None and not loc(d['root']):raise ValueError('root shape')
 for name,width in [('front16',4),('front64',16)]:
  if type(d[name])is not list or len(d[name])>4096:raise ValueError('front shape')
  for e in d[name]:
   if type(e)is not list or len(e)!=3 or type(e[0])is not str or len(e[0])!=width or not HEX.fullmatch(e[0])or not loc(e[1:]):raise ValueError('front entry shape')
 if type(d['cells'])is not list or len(d['cells'])!=11 or not all(integer(x,0,131072)for x in d['cells']):raise ValueError('cell shape')
 if type(d['banks'])is not list or len(d['banks'])!=11:raise ValueError('bank shape')
 for bank in d['banks']:
  if type(bank)is not list or len(bank)>65536:raise ValueError('bank bound')
  if not all(type(w)is str and len(w)==64 and HEX.fullmatch(w)for w in bank):raise ValueError('word shape')
 if sum(map(len,d['banks']))>65536:raise ValueError('word bound')
 if type(d['bitmaps'])is not list or len(d['bitmaps'])>8193 or not all(type(w)is str and len(w)==16 and HEX.fullmatch(w)for w in d['bitmaps']):raise ValueError('bitmap shape')
 if type(d['nexthops'])is not list or len(d['nexthops'])>8192 or not all(integer(x,0,4194302)for x in d['nexthops']):raise ValueError('NI shape')
def check_response(fixture,response):
 if fixture.get('invalid'):
  if response!={'error':'invalid'}:raise ValueError('invalid request response')
  return
 fields(response,'results');expected=fixture['expected']
 if type(response['results'])is not list or len(response['results'])!=len(expected):raise ValueError('case count')
 for result,wanted in zip(response['results'],expected):
  fields(result,'answers snapshots loads')
  if type(result['answers'])is not list or any(x is not None and not integer(x,0,4194302)for x in result['answers']):raise ValueError('answers shape')
  if result['answers']!=wanted['answers']:raise ValueError('sanity lookup answers')
  if type(result['loads'])is not list or any(type(x)is not bool for x in result['loads'])or result['loads']!=wanted['loads']:raise ValueError('sanity load result')
  if type(result['snapshots'])is not list or len(result['snapshots'])!=wanted['snapshots']:raise ValueError('snapshot count')
  for image in result['snapshots']:image_shape(image)
  if wanted.get('single_default'):
   d=result['snapshots'][0];hop=wanted['single_default'];s,a=d['root']
   word=4|(hop<<3)|(hop<<97)
   if a!=0 or sum(d['cells'])!=1 or d['cells'][s]!=1 or d['front16']or d['front64']or d['bitmaps']or d['nexthops']:raise ValueError('one-prefix compact image')
   if d['banks'][s]!=[f'{word:064x}']or sum(map(len,d['banks']))!=1:raise ValueError('one-prefix packed fields')
